?><link rel="stylesheet" href="../assets/css/staff-activity.css?v=20261028-1"><nav class="st-tabs" aria-label="System settings sections"><a href="layout.php?page=system_settings">Office settings</a><a href="layout.php?page=system_settings&amp;section=activity">Staff activity</a><a href="layout.php?page=system_settings&amp;section=delivery" aria-current="page">Email &amp; notifications</a></nav><section class="pn-delivery"><h2>Email &amp; notification delivery</h2><p>Website notifications appear immediately. Emails are sent from the background queue so submissions stay quick.</p><?php if(!empty($mailError)):?><p class="pn-error" role="alert"><?=$mailE($mailError)?></p><?php endif;?><?php if(!empty($_SESSION['settings_success'])):?><p role="status"><?=$mailE($_SESSION['settings_success'])?></p><?php unset($_SESSION['settings_success']);endif;?><p><strong><?=EmailConfiguration::ready()?'Email configured':'Email paused / setup needed'?></strong> · Sender: <?=$mailE(EmailConfiguration::masked($mailConfig['from_email']))?></p><div class="pn-delivery-stats"><?php foreach(['pending'=>'Waiting','processing'=>'Sending','sent'=>'Sent','failed'=>'Needs attention'] as $key=>$label):?><article><strong><?=$delivery[$key]?></strong><?=$label?></article><?php endforeach;?></div><p>Notification recipients: the submitting student or examinee, plus the guidance staff permitted to review that record. Emails contain a short update and a sign-in link.</p><p>Background worker last checked: <strong><?=$mailE($workerRun?:'Not yet recorded')?></strong> (Philippine time). The Windows job checks the queue every minute while this user is signed in and XAMPP is running.</p><section aria-labelledby="website-address-heading" style="border-top:1px solid #dce5ee;margin-top:24px;padding-top:20px"><h3 id="website-address-heading">Website address for email links</h3><p>Enter the address people use to open this website. When hosted online, use your published HTTPS address and include the folder if the site uses one.</p><form method="post" data-portal-save class="pn-mail-form"><input type="hidden" name="save_website_settings" value="1"><input type="hidden" name="office_settings_csrf" value="<?=$mailE($_SESSION['office_settings_csrf'])?>"><label class="pn-full">Website address<input type="url" name="website_url" maxlength="1500" value="<?=$mailE($websiteApp['base_url'])?>" required <?=WebsiteConfiguration::managed()?'readonly':''?> aria-describedby="website-url-help"><small id="website-url-help"><?=WebsiteConfiguration::managed()?'Managed by your hosting server through GUIDANCE_BASE_URL.':'Use the current local address while testing. Replace it with your public address after hosting.'?></small></label><p class="pn-full">Appointment email link: <span style="overflow-wrap:anywhere"><?=$mailE($websiteApp['base_url'].'/auth/login.php?mail=counseling')?></span><br><small>Recipients sign in and see the appointment page allowed for their role. Previously delivered emails keep their original links.</small></p><?php if(!WebsiteConfiguration::managed()):?><div class="pn-full"><button class="pn-save" type="submit">Save website address</button></div><?php endif;?></form></section><details><summary>Mail server settings</summary><form method="post" data-portal-save class="pn-mail-form"><input type="hidden" name="save_mail_settings" value="1"><input type="hidden" name="office_settings_csrf" value="<?=$mailE($_SESSION['office_settings_csrf'])?>"><label>SMTP server<input name="smtp_host" value="<?=$mailE($mailConfig['smtp_host'])?>" required></label><label>Port<input name="smtp_port" type="number" min="1" max="65535" value="<?=(int)$mailConfig['smtp_port']?>" required></label><label>Encryption<select name="smtp_secure"><option value="tls" <?=$mailConfig['smtp_secure']==='tls'?'selected':''?>>STARTTLS</option><option value="ssl" <?=$mailConfig['smtp_secure']==='ssl'?'selected':''?>>SSL / TLS</option></select></label><label>Mail account<input type="email" name="smtp_username" value="<?=$mailE($mailConfig['smtp_username'])?>" autocomplete="username" required></label><label>App password<input type="password" name="smtp_password" autocomplete="new-password"><small>Leave blank to keep the saved password.</small></label><label>Sender email<input type="email" name="from_email" value="<?=$mailE($mailConfig['from_email'])?>" required></label><label>Sender name<input name="from_name" value="<?=$mailE($mailConfig['from_name'])?>" required></label><label class="pn-check"><input type="checkbox" name="mail_enabled" value="1" <?=$mailConfig['enabled']?'checked':''?>> Enable email delivery</label><div class="pn-full"><button class="pn-save" type="submit">Save email settings</button></div></form></details></section>

